function serializeOptions(options) {
  if (options === null || typeof options !== "object") {
    throw new TypeError("options must be a plain object");
  }

  const prototype = Object.getPrototypeOf(options);
  if (prototype !== Object.prototype && prototype !== null) {
    throw new TypeError("options must be a plain object");
  }

  const hex = "0123456789ABCDEF";

  function encodeRFC3986(value) {
    const output = [];

    function appendByte(byte) {
      output.push("%", hex[byte >> 4], hex[byte & 0x0f]);
    }

    for (let i = 0; i < value.length; i += 1) {
      const first = value.charCodeAt(i);
      let codePoint;

      if (first >= 0xd800 && first <= 0xdbff) {
        if (i + 1 >= value.length) {
          throw new URIError("Unpaired surrogate");
        }

        const second = value.charCodeAt(i + 1);
        if (second < 0xdc00 || second > 0xdfff) {
          throw new URIError("Unpaired surrogate");
        }

        codePoint =
          0x10000 + ((first - 0xd800) << 10) + (second - 0xdc00);
        i += 1;
      } else if (first >= 0xdc00 && first <= 0xdfff) {
        throw new URIError("Unpaired surrogate");
      } else {
        codePoint = first;
      }

      const unreserved =
        (codePoint >= 0x30 && codePoint <= 0x39) ||
        (codePoint >= 0x41 && codePoint <= 0x5a) ||
        (codePoint >= 0x61 && codePoint <= 0x7a) ||
        codePoint === 0x2d ||
        codePoint === 0x2e ||
        codePoint === 0x5f ||
        codePoint === 0x7e;

      if (unreserved) {
        output.push(String.fromCharCode(codePoint));
      } else if (codePoint <= 0x7f) {
        appendByte(codePoint);
      } else if (codePoint <= 0x7ff) {
        appendByte(0xc0 | (codePoint >> 6));
        appendByte(0x80 | (codePoint & 0x3f));
      } else if (codePoint <= 0xffff) {
        appendByte(0xe0 | (codePoint >> 12));
        appendByte(0x80 | ((codePoint >> 6) & 0x3f));
        appendByte(0x80 | (codePoint & 0x3f));
      } else {
        appendByte(0xf0 | (codePoint >> 18));
        appendByte(0x80 | ((codePoint >> 12) & 0x3f));
        appendByte(0x80 | ((codePoint >> 6) & 0x3f));
        appendByte(0x80 | (codePoint & 0x3f));
      }
    }

    return output.join("");
  }

  const pairs = [];

  for (const name of Object.keys(options)) {
    const value = options[name];

    if (value === undefined) {
      continue;
    }

    let valueText;

    if (value === null) {
      valueText = "";
    } else if (typeof value === "string") {
      valueText = String(value);
    } else if (typeof value === "number" && Number.isFinite(value)) {
      valueText = String(value);
    } else if (typeof value === "boolean") {
      valueText = String(value);
    } else {
      throw new TypeError("Unsupported option value");
    }

    pairs.push([encodeRFC3986(name), encodeRFC3986(valueText)]);
  }

  pairs.sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    if (a[1] < b[1]) return -1;
    if (a[1] > b[1]) return 1;
    return 0;
  });

  return pairs.map(([name, value]) => name + "=" + value).join("&");
}
